    # Propagate: if a cell becomes 3 and its neighbor was 1, let's see if neighbors of the NEW 3s become 3
    iteration = 0
    while iteration < threshold:  # Limited iterations
        new_added = set()
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1 and (r, c) not in changed:
